{
  "name": "typeahead",
  "version": "1.0.0",
  "private": true,
  "description": "Instant typeahead / autocomplete search UI backed by Typesense",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "express": "^4.19.2",
    "typesense": "^1.8.2"
  }
}

"use strict";

const fs = require("fs");
const path = require("path");
const Typesense = require("typesense").Client;

const API_KEY_FILE = "/etc/typesense-api-key";
const COLLECTION_NAME = "cities";

function readApiKey() {
  if (process.env.TYPESENSE_API_KEY) {
    return process.env.TYPESENSE_API_KEY.trim();
  }
  return fs.readFileSync(API_KEY_FILE, "utf8").trim();
}

const client = new Typesense({
  nodes: [
    {
      host: process.env.TYPESENSE_HOST || "127.0.0.1",
      port: Number(process.env.TYPESENSE_PORT) || 8108,
      protocol: process.env.TYPESENSE_PROTOCOL || "http",
    },
  ],
  apiKey: readApiKey(),
  connectionTimeoutSeconds: 10,
});

const schema = {
  name: COLLECTION_NAME,
  fields: [
    { name: "name", type: "string" },
    { name: "country", type: "string" },
    { name: "population", type: "int32" },
  ],
  default_sorting_field: "population",
};

async function ensureCollection() {
  try {
    await client.collections(COLLECTION_NAME).retrieve();
  } catch (err) {
    if (err && err.httpStatus === 404) {
      await client.collections().create(schema);
    } else {
      throw err;
    }
  }
}

async function indexCities(cities) {
  await ensureCollection();
  if (!cities.length) return;
  const documents = cities.map((c) => ({
    id: String(c.id),
    name: c.name,
    country: c.country,
    population: c.population,
  }));
  await client
    .collections(COLLECTION_NAME)
    .documents()
    .import(documents, { action: "upsert" });
}

async function searchCities(query, limit = 8) {
  const trimmed = (query || "").trim();
  if (!trimmed) return [];

  const searchParameters = {
    q: trimmed,
    query_by: "name",
    prefix: true,
    num_typos: 2,
    typo_tokens_threshold: 1,
    drop_tokens_threshold: 0,
    per_page: limit,
    sort_by: "population:desc,name:asc",
  };

  const result = await client
    .collections(COLLECTION_NAME)
    .documents()
    .search(searchParameters);

  const hits = result.hits || [];
  return hits.slice(0, limit).map((hit) => {
    const doc = hit.document;
    return {
      id: String(doc.id),
      name: doc.name,
      country: doc.country,
      population: doc.population,
    };
  });
}

module.exports = {
  client,
  COLLECTION_NAME,
  ensureCollection,
  indexCities,
  searchCities,
};

"use strict";

const fs = require("fs");
const path = require("path");
const express = require("express");

const { indexCities, searchCities } = require("./lib/typesenseClient");

const PORT = process.env.PORT || 3000;
const DATA_FILE = path.join(__dirname, "data", "cities.json");

const app = express();
app.use(express.static(path.join(__dirname, "public")));

// In-memory lookup of cities by id, used for the detail view.
let citiesById = new Map();

function loadCitiesFromDisk() {
  const raw = fs.readFileSync(DATA_FILE, "utf8");
  const cities = JSON.parse(raw);
  citiesById = new Map(cities.map((c) => [String(c.id), c]));
  return cities;
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function renderDetailPage(city) {
  const name = escapeHtml(city.name);
  const country = escapeHtml(city.country);
  const population = escapeHtml(String(city.population));
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>${name} — City Details</title>
  <link rel="stylesheet" href="/style.css" />
</head>
<body>
  <main class="detail">
    <a class="back-link" href="/">&larr; Back to search</a>
    <h1 id="city-name">${name}</h1>
    <dl>
      <dt>Country</dt>
      <dd id="city-country">${country}</dd>
      <dt>Population</dt>
      <dd id="city-population">${population}</dd>
    </dl>
  </main>
</body>
</html>`;
}

app.get("/api/suggest", async (req, res) => {
  try {
    const q = typeof req.query.q === "string" ? req.query.q : "";
    const results = await searchCities(q, 8);
    res.status(200).json(results);
  } catch (err) {
    console.error("Error handling /api/suggest:", err);
    res.status(200).json([]);
  }
});

app.get("/item/:id", (req, res) => {
  const city = citiesById.get(String(req.params.id));
  if (!city) {
    res.status(404).send("City not found");
    return;
  }
  res.status(200).send(renderDetailPage(city));
});

async function start() {
  const cities = loadCitiesFromDisk();
  try {
    await indexCities(cities);
    console.log(`Indexed ${cities.length} cities into Typesense.`);
  } catch (err) {
    console.error("Failed to index cities into Typesense:", err);
  }

  app.listen(PORT, () => {
    console.log(`Typeahead app listening on port ${PORT}`);
  });
}

start();

