const { JSDOM } = require("jsdom");
const fs = require("fs");
const fetch = require("node-fetch");

async function main() {
  const html = fs.readFileSync("/home/user/typeahead/public/index.html", "utf8");
  const dom = new JSDOM(html, {
    url: "http://127.0.0.1:3000/",
    runScripts: "outside-only",
    resources: "usable",
  });

  const { window } = dom;
  window.fetch = fetch;

  const appJs = fs.readFileSync("/home/user/typeahead/public/app.js", "utf8");
  dom.window.eval(appJs);

  const document = window.document;
  const input = document.getElementById("q");
  const suggestionsEl = document.getElementById("suggestions");

  function setValue(val) {
    const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
      window.HTMLInputElement.prototype,
      "value"
    ).set;
    nativeInputValueSetter.call(input, val);
    const ev = new window.Event("input", { bubbles: true });
    input.dispatchEvent(ev);
  }

  function keydown(key) {
    const ev = new window.KeyboardEvent("keydown", { key, bubbles: true, cancelable: true });
    input.dispatchEvent(ev);
  }

  function wait(ms) {
    return new Promise((r) => setTimeout(r, ms));
  }

  // 1. Typing triggers debounce + fetch, then renders suggestions with <mark>.
  setValue("san");
  await wait(400); // wait past debounce (200ms) + fetch round trip

  let items = suggestionsEl.querySelectorAll(".suggestion");
  console.log("suggestion count after 'san':", items.length);
  console.log("first suggestion html:", items[0] ? items[0].innerHTML : null);
  console.log("has mark tag:", items[0] ? items[0].innerHTML.includes("<mark>") : false);

  // 2. ArrowDown activates first suggestion.
  keydown("ArrowDown");
  let active = suggestionsEl.querySelectorAll(".suggestion.active");
  console.log("active count after 1st ArrowDown:", active.length);
  console.log("active index after 1st ArrowDown:", active[0] ? active[0].getAttribute("data-index") : null);

  // 3. ArrowDown again moves to second.
  keydown("ArrowDown");
  active = suggestionsEl.querySelectorAll(".suggestion.active");
  console.log("active index after 2nd ArrowDown:", active[0] ? active[0].getAttribute("data-index") : null);

  // 4. ArrowUp moves back to first.
  keydown("ArrowUp");
  active = suggestionsEl.querySelectorAll(".suggestion.active");
  console.log("active index after ArrowUp:", active[0] ? active[0].getAttribute("data-index") : null);

  // 5. Escape closes dropdown.
  keydown("Escape");
  items = suggestionsEl.querySelectorAll(".suggestion");
  console.log("suggestion count after Escape:", items.length);

  // 6. Empty query clears dropdown.
  setValue("san");
  await wait(400);
  items = suggestionsEl.querySelectorAll(".suggestion");
  console.log("suggestion count after retyping 'san':", items.length);
  setValue("");
  await wait(50);
  items = suggestionsEl.querySelectorAll(".suggestion");
  console.log("suggestion count after clearing input:", items.length);

  process.exit(0);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

