const { JSDOM } = require('jsdom');
const fs = require('fs');
const fetch = require('node-fetch');

async function main(){
  const html = fs.readFileSync('/home/user/typeahead/public/index.html','utf8');
  const dom = new JSDOM(html, { url: 'http://127.0.0.1:3000/', runScripts: 'outside-only', resources: 'usable' });
  const { window } = dom;
  window.fetch = (url, opts) => fetch('http://127.0.0.1:3000'+url, opts);
  const appJs = fs.readFileSync('/home/user/typeahead/public/app.js','utf8');
  dom.window.eval(appJs);
  const document = window.document;
  const input = document.getElementById('q');
  const suggestionsEl = document.getElementById('suggestions');
  function setValue(val){
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
    setter.call(input, val);
    input.dispatchEvent(new window.Event('input',{bubbles:true}));
  }
  function keydown(key){ input.dispatchEvent(new window.KeyboardEvent('keydown',{key,bubbles:true,cancelable:true})); }
  function wait(ms){ return new Promise(r=>setTimeout(r,ms)); }
  setValue('san');
  await wait(400);
  keydown('ArrowDown');
  let active = suggestionsEl.querySelector('.suggestion.active');
  console.log('active id:', active.getAttribute('data-id'));
  let navigatedTo = null;
  Object.defineProperty(window, 'location', { value: { set href(v){ navigatedTo = v; }, get href(){return navigatedTo;} }, writable:true });
  keydown('Enter');
  console.log('navigated to:', navigatedTo);
  process.exit(0);
}
main().catch(e=>{console.error(e);process.exit(1);});
